
from enum import Enum
from typing import Self
import threading

from xLPyBasics import Sentinels as df
from xLPyBasics.ConsoleAPI import LoggerRegistry

import SoundInterface
import Core as Core
from Core import (
    LogChannel
)
import Sounds
from Sounds import (
    SoundOptions, VoiceOptions, CategoryOptions
)

# deletion time class
class DeletionTime:
    def __init__(
            self: Self,
            deletion_interval: int|None,
            deletion_error_max: int|df.Type.Infinite
    ) -> None:
        """Holds deletion time info

        Params:
            deletion_interval - controls how long between deletion attempts for this event
                - None means this event is not error prone (deletion is handled solely by roblox or the game activity checker)
            deletion_error_max - determines how many intervals pass before erroring trying to delete
        """

        self.deletion_interval = deletion_interval 
        self.deletion_count_max = deletion_error_max

# event option class
class EventOption:
    def __init__(
        self: Self, 
        name: str, 
        association: CategoryOptions|SoundOptions,
        deletion_settings: DeletionTime
    ) -> None:
        self.name = name
        self.association = association
        self.deletion_settings = deletion_settings

    def associtation_is_categoric(self: Self): 
        return isinstance(self.association, CategoryOptions)

# enum helper for deletion intervals
    # you aren't required to use this, it just improves readability
class DeletionSettings(Enum):
    Node = DeletionTime(5, 40)
    Eyefestation = DeletionTime(10, 20)
    Room = DeletionTime(30, df.Value.Infinite)
    none = DeletionTime(None, df.Value.Infinite)

# enum of event names
class EventOptions(Enum):
    AnglerFar = EventOption(
        "angler incoming", 
        CategoryOptions.Angler, 
        DeletionSettings.Node.value)
    PinkieFar = EventOption(
        "pinkie incoming", 
        CategoryOptions.Pinkie, 
        DeletionSettings.Node.value)
    SearchlightsMusic = EventOption(
        "searchlights upcoming", 
        CategoryOptions.Searchlights, 
        DeletionSettings.none.value)
    AbominationMusic = EventOption(
        "abomination upcoming", 
        CategoryOptions.Abomination, 
        DeletionSettings.none.value)
    FirewallElevatorMusic = EventOption(
        "firewall upcoming", 
        CategoryOptions.Firewall, 
        DeletionSettings.none.value)
    EyefestationNoise = EventOption(
        "eyefestation upcoming", 
        CategoryOptions.Eyefestation1, 
        DeletionSettings.Eyefestation.value)
    EyefestationMusic1 = EventOption(
        "eyefestation 2 upcoming", 
        CategoryOptions.Eyefestation2, 
        DeletionSettings.Eyefestation.value)
    EyefestationMusic2 = EventOption(
        "eyefestation 3 upcoming", 
        CategoryOptions.Eyefestation3, 
        DeletionSettings.Eyefestation.value)
    EyefestationTalking = EventOption(
        "eyefestation talking", 
        None, 
        DeletionSettings.Eyefestation.value)
    Lobby1 = EventOption(
        "lobby test marker confirmed system is online", 
        SoundOptions.Lobby, 
        DeletionSettings.none.value)
    Lobby2 = EventOption(
        "lobby test marker confirmed system is online", 
        SoundOptions.Lobby, 
        DeletionSettings.none.value)
    WaterNoisesAtStart = EventOption(
        "start reached",
        CategoryOptions.Enter, 
        DeletionSettings.none.value)
    TiedCrystal = EventOption(
        "crystal reached", 
        CategoryOptions.Crystal,
        DeletionSettings.none.value)
    RidgeEndingSpeech = EventOption(
        "end reached", 
        None, 
        DeletionSettings.none.value)
    OxygenGardensMusic = EventOption(
        "oxygen gardens reached", 
        CategoryOptions.OxygenGardens, 
        DeletionSettings.Room.value)
    Dredge = EventOption(
        "the dredge reached",
        CategoryOptions.Dredge.value,
        DeletionSettings.Room.value)

# error noises for error prone events
    # <name>: <key> such that EventOptions (event): (leading to) SoundOptions (sound)
ERROR_SOUNDS = {
    EventOptions.AnglerFar: SoundOptions.AnglerError,
    EventOptions.PinkieFar: SoundOptions.PinkieError,
    EventOptions.EyefestationNoise: SoundOptions.EyefestationError,
    EventOptions.EyefestationMusic1: SoundOptions.EyefestationError,
    EventOptions.EyefestationMusic2: SoundOptions.EyefestationError,
    EventOptions.EyefestationTalking: SoundOptions.EyefestationError
}

# eyefestation helpers
eyefestation_enrage_level: int = 1
eyefestation_music_recently_played: bool = False
def reset_eyefestation_music_recently_played() -> None: 
    global eyefestation_music_recently_played
    eyefestation_music_recently_played = False
    LoggerRegistry.log_at(LogChannel.SettingChange, "set eyefestation music to false")
eyefestation_talking_recently_played: bool = False
def reset_eyefestation_talking_recently_played() -> None: 
    global eyefestation_talking_recently_played
    eyefestation_talking_recently_played = False
    LoggerRegistry.log_at(LogChannel.SettingChange, "set eyefestation talking to false")

# event specifics
def event_specifics(eventOption: EventOptions) -> bool:
    global eyefestation_enrage_level
    global eyefestation_talking_recently_played
    global eyefestation_music_recently_played
    match (eventOption):
        # game state handling
        case EventOptions.WaterNoisesAtStart: 
            SoundInterface.currently_in_game = True
            LoggerRegistry.log_at(LogChannel.Log, "game is now started: water noises at start")
        case EventOptions.Lobby1 | EventOptions.Lobby2:
            SoundInterface.currently_in_game = False
            SoundInterface.handler.gif_button.config(state="active")
            LoggerRegistry.log_at(LogChannel.Log, "game is now stopped: lobby")
        case EventOptions.RidgeEndingSpeech: # (stops normal execution)
            SoundInterface.currently_in_game = False
            SoundInterface.handler.gif_button.config(state="active")
            LoggerRegistry.log_at(LogChannel.Log, "game is now stopped: ridge ending speech")
            return False # do not attempt to play a sound for this (it's none so it would crash)
            
        # eyefestation tracking (if (first time) then (stops normal execution) else (forwards to -> run normally))
        case EventOptions.EyefestationTalking:
            # signal that talking played for 2 seconds
            eyefestation_talking_recently_played = True # immediately change value
            LoggerRegistry.log_at(LogChannel.SettingChange, "set eyefestation talking to true")
            # change the value 2 seconds later
            threadT = threading.Timer(2, reset_eyefestation_talking_recently_played)
            threadT.daemon = True
            threadT.start()
            return False # never executes normally
        case EventOptions.EyefestationNoise:
            # level 1 check (after 1 second delay)
            def check_eyefestation_level_1():
                global eyefestation_music_recently_played

                if (eyefestation_music_recently_played):
                    LoggerRegistry.log_at(LogChannel.SettingChange, "passed eyefestation level 1")
                    return # don't do anything, another event has already played
                else: # play eyefestation 1 sound
                    LoggerRegistry.log_at(LogChannel.SettingChange, "found eyefestation level 1")
                    Sounds.play_sound_categoric_random(CategoryOptions.Eyefestation1)

            # wait 1 second and see if music also played
            thread1 = threading.Timer(1, check_eyefestation_level_1)
            thread1.daemon = True
            thread1.start()
            return False # never executes normally
        case EventOptions.EyefestationMusic1:
            # signal that music played for 2 seconds
            eyefestation_music_recently_played = True # immediately change value
            Core.sound_handler.print("+ set eyefesation music to trues")
            # change value back 2 seconds later
            thread2 = threading.Timer(2, reset_eyefestation_music_recently_played)
            thread2.daemon = True
            thread2.start()

            # wait 1 second before continuing checks
            def check_eyefestation_level_2():
                global eyefestation_talking_recently_played
                global eyefestation_enrage_level

                # check if it's not a gauntlet
                if (not eyefestation_talking_recently_played):

                    # check enragement level
                    if (eyefestation_enrage_level == 1):
                        LoggerRegistry.log_at(LogChannel.SettingChange, "+ found enragement 2")
                        Sounds.play_sound_categoric_random(CategoryOptions.Enragement2)
                
                        # incremenet
                        eyefestation_enrage_level = 2
                    elif (eyefestation_enrage_level == 2): # play normal
                        LoggerRegistry.log_at(LogChannel.SettingChange,"+ found eyefestation 2")
                        Sounds.play_sound_categoric_random(CategoryOptions.Eyefestation2)
                    else: # it should be impossible to get here
                        LoggerRegistry.log_at(LogChannel.SettingChange, "passed eyefestation level 2")
            thread21 = threading.Timer(1, check_eyefestation_level_2)
            thread21.daemon = True
            thread21.start()
            return False # never executes normally
        case EventOptions.EyefestationMusic2:
            # signal that music played for 2 seconds
            eyefestation_music_recently_played = True # immediately change value
            LoggerRegistry.log_at(LogChannel.SettingChange, "set eyefestation music to true")
            # change value back 2 seconds later
            thread3 = threading.Timer(2, reset_eyefestation_music_recently_played)
            thread3.daemon = True
            thread3.start()

            # check enragement level
            if (eyefestation_enrage_level == 2):
                LoggerRegistry.log_at(LogChannel.SettingChange, "found enragement 3")

                # if GIF is enabled 
                if (Sounds.voices[VoiceOptions.GIF].is_enabled):
                    Sounds.play_sound_categoric(VoiceOptions.GIF, CategoryOptions.Enragement3)
                    SoundInterface.handler.gif_button.config(state="disabled")
                    LoggerRegistry.log_at(LogChannel.Log, f"set the new value for {VoiceOptions.GIF.name} to {False}")
                    Sounds.voices[VoiceOptions.GIF].is_enabled = False
                    return False # early return

                # play enrage
                Sounds.play_sound_categoric_random(CategoryOptions.Enragement3)
        
                # incremenet
                eyefestation_enrage_level = 3
            elif (eyefestation_enrage_level == 3): # play normal
                LoggerRegistry.log_at(LogChannel.SettingChange, "found eyefestation level 3")
                Sounds.play_sound_categoric_random(CategoryOptions.Eyefestation3)
            else: # it should be impossible to get here
                LoggerRegistry.log_at(LogChannel.SettingChange, "passed level eyefestation 3")
            return False # never executes normally
        # default
        case _: pass # forward to -> run normally
    return True # run normally

